-- M10.StockOutward: new flow_variant registered by Dhivya (2026-09-18) as an
-- exact clone of M10.FGLoading's state machine -- same states, same
-- transitions, same guards, only the workflow code changed. Rides entirely
-- on the SAME existing pages M10.FGLoading already uses (aria:dispatch-
-- vehicle-details, aria:loading-planning-order-sheet-upload,
-- aria:loading-allocation, aria:weighment-capture,
-- aria:loading-in-progress-entry, aria:sealing-process,
-- aria:manager-qty-approval, aria:pmt-camera-verification,
-- aria:billing-entry, aria:manager-weight-approval,
-- aria:gate-pass-closure-form, aria:skipped-item-allocation,
-- aria:reject-flow-unloading) -- zero new pages, zero new Java.
--
-- Deliberately scoped to ONLY the FSM + its data-projection wiring
-- (workflow_definition + m0_workflow_projection), matching the M10.OtherVehicles
-- precedent (V259): those existing pages' own JSON still branches on the
-- LITERAL string 'M10.FGLoading' in a number of visibleWhen/computedFrom
-- conditions (e.g. aria:weighment-capture's weight_seq calculation), so
-- fields tuned for FG Loading will NOT automatically show/compute the same
-- way for M10.StockOutward instances yet. Confirmed with Dhivya this is
-- intentional for now -- extending each affected page's conditions is a
-- separate, later change, not part of this one.
--
-- m0_workflow_projection rows cloned: only the ones whose page_code actually
-- appears in this FSM's own transitions (dispatch_vehicle_detail, gate_pass,
-- loading_allocation_detail, weighment_capture_detail, sealing_process_detail,
-- pmt_camera_verification_detail, loading_progress_detail, gate_pass_closure,
-- billing_entry) -- M10.FGLoading also carries qc_preload_detail/
-- qc_unloading_approval rows (aria:qc-preload-approval / aria:qc-approval)
-- left out here since neither page appears anywhere in this FSM's
-- transitions; they'd never fire for this workflow anyway.
--
-- Idempotent throughout -- safe to (re)run on any database.

INSERT IGNORE INTO `m10_flow_variant` (`code`, `display_name`) VALUES
('M10.StockOutward', 'Stock Outward');

